mapper.sql:
where source = #{source}

    and category = #{category}


    and find_in_set(#{tag}, tags) > 0



    and (

        find_in_set(#{t}, tags) > 0

    )




    and not (

        coalesce(find_in_set(#{bt}, tags), 0) > 0

    )



    and (title like concat('%', #{qLike}, '%') or tags like concat('%', #{qLike}, '%'))




            and (match(title, content_text) against(#{ftQuery} in boolean mode)
                 or title like concat('%', #{qLike}, '%')
                 or tags like concat('%', #{qLike}, '%'))


            and match(title, content_text) against(#{ftQuery} in boolean mode)





        and (title like concat('%', #{lt}, '%') or coalesce(content_text, '') like concat('%', #{lt}, '%'))






        and featured_kind in ('home','both')
        and featured_kind in ('pinned','both')
        and featured = 1



    and published_ts >= #{dateFrom}


    and published_ts <= #{dateTo}




        and has_video = 1 and video_count > 0
        and (has_video = 0 or video_count = 0 or video_count is null)




    and ifnull(video_count, 0) >= #{minVideos}



    and orientation = #{orientation}

mapper.select:
select date_format(published_ts, '%Y-%m-%d') as day, count(*) as c
from tool_web_post
where source = #{source}
  and published_ts is not null
  and published_ts between #{from} and #{to}
and category = #{category}
and find_in_set(#{tag}, tags) > 0
group by published_ts
order by published_ts

select count(*) from tool_web_post t
where t.source = #{source}
  and coalesce(t.published_full, cast(t.published_ts as datetime), '1970-01-01') > #{dateTo}
and t.category = #{category}
and find_in_set(#{tag}, t.tags) > 0

select count(*) from tool_web_post t join (select id tid, coalesce(published_full, cast(published_ts as datetime), '1970-01-01') k, cast(source_id as unsigned) sid from tool_web_post where id = #{postId}) x where t.source = #{source}
and t.category = #{category}
and find_in_set(#{tag}, t.tags) > 0
and (
find_in_set(#{t2}, t.tags) > 0
)
and not (
coalesce(find_in_set(#{bt}, t.tags), 0) > 0
)
and t.published_ts >= #{dateFrom}
and t.published_ts <= #{dateTo}
and t.featured_kind in ('home','both') and t.featured_kind in ('pinned','both') and t.featured = 1
and t.id <> x.tid and (coalesce(t.published_full, cast(t.published_ts as datetime), '1970-01-01') > x.k or (coalesce(t.published_full, cast(t.published_ts as datetime), '1970-01-01') = x.k and cast(t.source_id as unsigned) > x.sid))

select post_id from tool_web_user_item
where owner_key = #{ownerKey} and kind = #{kind}
order by created_at desc
limit #{limit}
